import sys

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]

    kpos = []
    vpos = []
    opos = []

    for i, ch in enumerate(s):
        if ch == 'V':
            vpos.append(i)
        elif ch == 'K':
            kpos.append(i)
        else:
            opos.append(i)

    nk = len(kpos)
    nv = len(vpos)
    no = len(opos)

    INF = 10**9
    # Initialize 4D DP array
    dp = [[[[INF for _ in range(no + 1)] for _ in range(nv + 1)] for _ in range(nk + 1)] for _ in range(2)]
    dp[0][0][0][0] = 0

    for k in range(nk + 1):
        for v in range(nv + 1):
            for o in range(no + 1):
                for h in range(2):
                    val = dp[h][k][v][o]
                    if val == INF:
                        continue
                    if k < nk and h == 0:
                        cost = val + max(kpos[k] - v, 0) + max(kpos[k] - o, 0)
                        if cost < dp[0][k + 1][v][o]:
                            dp[0][k + 1][v][o] = cost
                    if v < nv:
                        cost = val + max(vpos[v] - k, 0) + max(vpos[v] - o, 0)
                        if cost < dp[1][k][v + 1][o]:
                            dp[1][k][v + 1][o] = cost
                    if o < no:
                        cost = val + max(opos[o] - v, 0) + max(opos[o] - k, 0)
                        if cost < dp[0][k][v][o + 1]:
                            dp[0][k][v][o + 1] = cost

    answer = min(dp[0][nk][nv][no], dp[1][nk][nv][no])
    print(answer)

if __name__ == "__main__":
    main()

